/* report.c — envious */
void report_build(const struct date *d, const struct state *s) {
    printf("%04d-%02d-%02d %s", d->year, d->month, d->day, s->title);
}

/* date.c — behaviour with the data */
void date_iso(const struct date *d, char out[11]) {
    snprintf(out, 11, "%04d-%02d-%02d", d->year, d->month, d->day);
}
